"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34457"],{61441(e){e.exports=JSON.parse('{"id":"FIN-413","slug":"terminal-growth-rate","term":"Terminal Growth Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The terminal growth rate is the constant annual rate at which a company\'s cash flows are assumed to grow forever after the end of the detailed forecast period in a discounted cash flow valuation.","explanation":["In a DCF, analysts forecast cash flows year by year for a limited period, often five to ten years. After that, they assume the business settles into steady, long-term growth. The terminal growth rate represents this growth and is used to calculate the terminal value.","Because no company can grow faster than the whole economy forever, the terminal growth rate is usually set at or below the expected long-term growth of the economy, often in the range of about 2% to 3% in many developed economies, reflecting long-term inflation and real growth.","The choice has a large effect on value. Suppose cash flow in the first year after the forecast period is 10 million and the discount rate is 9%. With a terminal growth rate of 2%, the terminal value is about 143 million. With 3%, it rises to about 167 million.","Because the terminal value often makes up a large share of the total valuation, analysts test how sensitive their results are to different terminal growth rates and compare them with values from other methods, such as exit multiples."],"note":"","total":1500,"prev":{"slug":"term-sheet","term":"Term Sheet"},"next":{"slug":"terminal-value","term":"Terminal Value"}}')}}]);